import { ActionDefinition } from '../../../Action'
import {
    TableNameColumn,
    StringColumn,
    BooleanColumn,
    DocumentIdColumn,
    ReferenceColumn,
    HtmlColumn,
} from '../../../../db'

export const sendEmail = ActionDefinition({
    $id: 'c1806bf4a70323008299b39f087901cb',
    name: 'Send Email',
    description:
        'Send rich text emails to a comma separated list of email addresses, user records, and group records. If user records do not have an email address configured, the email will not be sent to that user.   Use pills to decorate the subject line and email body. Note: Commas are not required between pills, only static email addresses',
    inputs: {
        table_name: TableNameColumn({
            label: 'Table',
        }),
        ah_cc: StringColumn({
            label: 'CC',
            maxLength: 8000,
        }),
        watermark_email: BooleanColumn({
            label: 'Include Watermark',
            default: true,
        }),
        ah_bcc: StringColumn({
            label: 'BCC',
            maxLength: 8000,
        }),
        ah_subject: StringColumn({
            label: 'Subject',
            mandatory: true,
            maxLength: 8000,
        }),
        ah_body: HtmlColumn({
            label: 'Body',
            maxLength: 65536,
            columnType: 'html',
        }),
        record: DocumentIdColumn({
            label: 'Target Record',
            dependent: 'table_name',
            tableReference: true,
        }),
        ah_to: StringColumn({
            label: 'To',
            mandatory: true,
            maxLength: 8000,
        }),
    },
    outputs: {
        email: ReferenceColumn({
            label: 'email',
            referenceTable: 'sys_email',
        }),
    },
})
